/**
 * @vitest-environment happy-dom
 *
 * Per-tool golden snapshots for `populateToolPropertyPanel`. Lives
 * here as the regression net after Phase 3 of
 * `docs/plans/tool-property-renderer-schema.md` deleted the
 * imperative renderer + the side-by-side byte-equivalence cross-
 * check it powered.
 *
 * Each test renders one tool's panel into a fresh `<div>` and pins
 * the resulting `outerHTML` via `toMatchInlineSnapshot`. The
 * snapshots live inline so a reviewer reading the diff sees the
 * exact DOM change a code edit produces; intentional UX edits
 * (e.g. Phase 5's tooltip-label cleanup) update the snapshots in
 * the same PR.
 *
 * The snapshots cover: every panel-rendering tool × every variant,
 * plus the fresh-preset (default-variant seeding) flow. Empty-render
 * cases (`crop`, unknown toolIds) round out the "renderer never
 * throws" guarantee.
 */

import { describe, expect, it } from "vitest";
import type { CanvasManager } from "@ingcreators/annot-editor";
import type { ToolOptions } from "@ingcreators/annot-core/editor/tool-options";

import {
  populateToolPropertyPanel,
  type ToolPropertyRendererContext,
} from "./tool-property-renderer.js";

// ─── Fixtures ────────────────────────────────────────────────────────

function basePreset(): ToolOptions {
  return {
    strokeColor: "#222222",
    fillColor: "#ffaa00",
    strokeWidth: 2,
    fontSize: 16,
    strokeDasharray: "dash",
    fillOpacity: 0.6,
    strokeOpacity: 0.85,
    strokeLinecap: "round",
  };
}

function presetWith(overrides: Partial<ToolOptions>): ToolOptions {
  return { ...basePreset(), ...overrides };
}

function strippedPreset(): ToolOptions {
  // No variant fields set — exercises the default-variant seeding
  // path (`seedDefaultVariantIfNeeded` in the renderer).
  return {
    strokeColor: "#000000",
    fillColor: "#ffffff",
    strokeWidth: 1,
    fontSize: 14,
    strokeDasharray: "",
    fillOpacity: 1,
  };
}

function deepClone<T>(value: T): T {
  return JSON.parse(JSON.stringify(value)) as T;
}

interface RendererFixture {
  menu: HTMLElement;
  ctx: ToolPropertyRendererContext;
}

function makeFixture(initial: ToolOptions): RendererFixture {
  const presetMap = new Map<string, ToolOptions>();
  const canvas = { activeTool: null } as unknown as CanvasManager;
  const ctx: ToolPropertyRendererContext = {
    canvas,
    options: deepClone(initial),
    getCurrentPreset: (toolId) => {
      let p = presetMap.get(toolId);
      if (!p) {
        p = deepClone(initial);
        presetMap.set(toolId, p);
      }
      return p;
    },
    saveCurrentPreset: (toolId, p) => {
      presetMap.set(toolId, p);
    },
    handlePanelVariantChange: () => {
      // Snapshot tests don't simulate variant chip clicks; the click
      // handler isn't part of outerHTML so its presence is invisible
      // to the snapshot anyway.
    },
  };
  const menu = document.createElement("div");
  menu.className = "tool-properties-menu";
  return { menu, ctx };
}

function renderToolHtml(toolId: string, initial: ToolOptions): string {
  const { menu, ctx } = makeFixture(initial);
  populateToolPropertyPanel(toolId, menu, ctx);
  return menu.outerHTML;
}

// ─── Per-tool golden snapshots ───────────────────────────────────────

