// ─── Empty / no-op cases ─────────────────────────────────────────────

describe("populateToolPropertyPanel — empty / no-op cases", () => {
  it("produces an empty menu for tools without panelControls (crop)", () => {
    const { menu, ctx } = makeFixture(basePreset());
    populateToolPropertyPanel("crop", menu, ctx);
    expect(menu.children.length).toBe(0);
  });

  it("produces an empty menu for unknown toolIds", () => {
    const { menu, ctx } = makeFixture(basePreset());
    populateToolPropertyPanel("nonexistent-tool", menu, ctx);
    expect(menu.children.length).toBe(0);
  });
});
